-- ============================================================================
-- FraudGuard Database Migration: V5__sar_reports.sql
-- Engine: MySQL 8.0+
-- SAR reports generated by Gemini AI for compliance filing.
-- ============================================================================

CREATE TABLE sar_reports (
  id                 CHAR(36) NOT NULL,
  transaction_id     CHAR(36) NOT NULL,
  generated_by       CHAR(36) NOT NULL,
  report_text        TEXT NOT NULL,
  model_used         VARCHAR(100) NOT NULL DEFAULT 'gemini-2.0-flash',
  prompt_token_count INT,
  output_token_count INT,
  generation_ms      BIGINT,
  status             VARCHAR(30) NOT NULL DEFAULT 'DRAFT',
  filed_at           DATETIME(6),
  filed_by           CHAR(36),
  notes              TEXT,
  created_at         DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at         DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  CONSTRAINT chk_sar_status CHECK (status IN ('DRAFT','FINAL','FILED')),
  CONSTRAINT fk_sar_transaction FOREIGN KEY (transaction_id) REFERENCES transactions(id) ON DELETE RESTRICT,
  CONSTRAINT fk_sar_generated_by FOREIGN KEY (generated_by) REFERENCES users(id) ON DELETE RESTRICT,
  CONSTRAINT fk_sar_filed_by FOREIGN KEY (filed_by) REFERENCES users(id) ON DELETE SET NULL
);

CREATE INDEX idx_sar_transaction  ON sar_reports(transaction_id);
CREATE INDEX idx_sar_generated_by ON sar_reports(generated_by);
CREATE INDEX idx_sar_status       ON sar_reports(status);
CREATE INDEX idx_sar_created      ON sar_reports(created_at DESC);

-- Auto-update updated_at (MySQL trigger replacing PL/pgSQL function)
DELIMITER $$

CREATE TRIGGER trg_sar_updated_at
BEFORE UPDATE ON sar_reports
FOR EACH ROW
BEGIN
    SET NEW.updated_at = NOW(6);
END$$

DELIMITER ;
